//  pages exist, and is there a next one? Zero items means zero pages.

using static Bootcamp.Check;

int TotalPages(int totalItems, int pageSize)
{
    return (totalItems + pageSize - 1) / pageSize;   // 0 items -> (pageSize - 1) / pageSize = 0
}

bool HasNext(int page, int totalItems, int pageSize)
{
    return page < TotalPages(totalItems, pageSize);
