//  Two admins edit the same record; the second save must not silently
//  overwrite the first. If-Match against a versioned ETag stops it.

using static Bootcamp.Check;

string ETagOf(int version)
{
    return $"\"v{version}\"";
}

bool PreconditionHolds(string? ifMatch, string etag)
{
    if (ifMatch is null) return false;
