// ─────────────────────────────────────────────────────────────────────────
//  09 · conditional create                                     ★★☆ core
//  concepts: If-None-Match: * · If-Match · 412 Precondition Failed
// ─────────────────────────────────────────────────────────────────────────
//
//  PUT /items/{id} can create OR replace. Two clients both "creating" the
//  same id must not overwrite each other: the client says which outcome it
//  expects, and the server refuses the write when the expectation is wrong.

using static Bootcamp.Check;

int PutStatus(bool exists, string? currentEtag, string? ifMatch, string? ifNoneMatch)
{
    // RFC 9110 §13.2.2 order: If-Match first, then If-None-Match.
    if (ifMatch is not null)
    {
        bool matches = exists && (ifMatch == "*" || ifMatch == currentEtag);
        if (!matches) return 412;
    }
    if (ifNoneMatch is not null)
    {
        bool noneMatch = ifNoneMatch == "*" ? !exists : !(exists && ifNoneMatch == currentEtag);
        if (!noneMatch) return 412;
    }
    return exists ? 200 : 201;
}

